import { useLocation, useNavigate } from "react-router-dom";
import { useEffect } from "react";

function Dashboard() {
    const location = useLocation();
    const navigate = useNavigate();
    const responseData = location.state?.response;

    useEffect(() => {
        if (!responseData) {
            navigate("/login");
        }
    }, [responseData, navigate]);

    if (!responseData) {
        return <p>Redirecting to login...</p>;
    }

    return (
        <div className="container">
            <h1>Dashboard</h1>
            <div style={{ padding: "20px", backgroundColor: "#f0f0f0", borderRadius: "10px" }}>
                <h3>Status: {responseData.Status}</h3>
                <h3>Message: {responseData.Message}</h3>
                {responseData.UserInfo && (
                    <>
                        <h4>User Info:</h4>
                        <pre>{JSON.stringify(responseData.UserInfo, null, 2)}</pre>
                    </>
                )}
            </div>
        </div>
    );
}

export default Dashboard;
